1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Models;
6	
7	use AtrioTeam\DigitalHub\Assets\Concerns\HasAssets;
8	use AtrioTeam\DigitalHub\Assets\Contracts\OwnsAssets;
9	use AtrioTeam\DigitalHub\Identity\Concerns\HasGlobalId;
10	use AtrioTeam\DigitalHub\Pim\AttributeSchema;
11	use AtrioTeam\DigitalHub\Pim\Concerns\HasTechnicalAttributes;
12	use AtrioTeam\DigitalHub\Tags\Models\Tag;
13	use Illuminate\Database\Eloquent\Model;
14	use Illuminate\Database\Eloquent\Relations\BelongsTo;
15	use Illuminate\Database\Eloquent\Relations\BelongsToMany;
16	use Illuminate\Database\Eloquent\Relations\HasMany;
17	use InvalidArgumentException;
18	use Laravel\Scout\Searchable;
19	use Spatie\MediaLibrary\HasMedia;
20	use Spatie\Tags\HasTags;
21	use Spatie\Translatable\Attributes\Translatable;
22	use Spatie\Translatable\HasTranslations;
23	
24	#[Translatable('name')]
25	class Product extends Model implements HasMedia, OwnsAssets
26	{
27	    use HasAssets;
28	    use HasGlobalId;
29	    use HasTags;
30	    use HasTechnicalAttributes;
31	    use HasTranslations;
32	    use Searchable;
33	
34	    protected $guarded = [];
35	
36	    /**
37	     * Colonne reali su cui il driver "database" di Scout costruisce le
38	     * LIKE (roadmap #23): le chiavi devono corrispondere a colonne della
39	     * tabella, non a valori arbitrari. `name_search` è una colonna generata
40	     * STORED (cast a testo di `name`, JSON translatable): MySQL confronta il
41	     * JSON grezzo con LIKE usando collation binaria (case-sensitive) a
42	     * prescindere dalla collation di connessione, il cast la aggira. Match
43	     * grezzo su tutte le lingue incluso.
44	     *
45	     * @return array<string, mixed>
46	     */
47	    public function toSearchableArray(): array
48	    {
49	        return [
50	            'name_search' => $this->getAttribute('name_search'),
51	            'slug' => $this->slug,
52	        ];
53	    }
54	
55	    protected static function booted(): void
56	    {
57	        // strategia orfani (opzione C, design §3.6): al salvataggio rimuove dal JSON
58	        // degli attributi le chiavi non più previste dallo schema corrente (risolto
59	        // dalla tipologia già assegnata sul record). L'utente è avvisato a monte
60	        // dall'alert inline nel ProductForm; qui avviene lo strip effettivo.
61	        static::saving(function (self $product): void {
62	            // se la tipologia è cambiata, la relazione productType potrebbe essere
63	            // ancora quella vecchia in cache: la scarico così lo schema viene
64	            // risolto dalla tipologia appena assegnata.
65	            if ($product->isDirty('product_type_id')) {
66	                $product->unsetRelation('productType');
67	            }
68	
69	            $product->setAttribute(
70	                $product->attributesColumn(),
71	                $product->stripOrphanAttributes($product->attributeSchema()),
72	            );
73	        });
74	    }
75	
76	    /**
77	     * Lo schema attributi del Product è determinato dalla ProductType associata.
78	     * Se la ProductType non ha uno schema configurato, il prodotto non ha attributi tipizzati.
79	     */
80	    public function resolveAttributeSchemaClass(): ?string
81	    {
82	        $class = $this->productType?->attribute_schema_class;
83	
84	        return is_string($class) && is_subclass_of($class, AttributeSchema::class) ? $class : null;
85	    }
86	
87	
88	    /**
89	     * Nome comprensivo del nome collezione (category2)
90	     */
91	    public function catalogName(?string $locale = null): string
92	    {
93	        $locale ??= app()->getLocale();
94	        // @phpstan-ignore binaryOp.invalid,binaryOp.invalid
95	        return $this->category2?->getTranslation('name', $locale)
96	            . ' ' . $this->getTranslation('name', $locale);
97	    }
98	
99	    /**
100	     * Padre nella composizione (il "divano modulare" wrapper). Null per i
101	     * prodotti non componibili e per gli stessi wrapper.
102	     *
103	     * @return BelongsTo<Product, $this>
104	     */
105	    public function parent(): BelongsTo
106	    {
107	        return $this->belongsTo(self::class, 'parent_id');
108	    }
109	
110	    /**
111	     * I moduli che compongono questo prodotto (adjacency list).
112	     *
113	     * @return HasMany<Product, $this>
114	     */
115	    public function modules(): HasMany
116	    {
117	        return $this->hasMany(self::class, 'parent_id');
118	    }
119	
120	    /**
121	     * @return BelongsTo<Category2, $this>
122	     */
123	    public function category2(): BelongsTo
124	    {
125	        return $this->belongsTo(Category2::class, 'category_2_id');
126	    }
127	
128	    /**
129	     * @return BelongsTo<ProductType, $this>
130	     */
131	    public function productType(): BelongsTo
132	    {
133	        return $this->belongsTo(ProductType::class);
134	    }
135	
136	    /**
137	     * Materiali (finiture dure) del prodotto (singola finitura).
138	     *
139	     * @return BelongsToMany<Material, $this>
140	     */
141	    public function materials(): BelongsToMany
142	    {
143	        return $this->belongsToMany(Material::class, 'material_product', 'product_id', 'material_id');
144	    }
145	
146	    /**
147	     * Materiali assegnati al prodotto che, tra i loro tag, ne hanno uno con il
148	     * dato valore sull'asse "finalità" (es. struttura, piano_tavolo, ...).
149	     *
150	     * @return BelongsToMany<Material, $this>
151	     */
152	    public function materialsForFinalita(string $value): BelongsToMany
153	    {
154	        $tags = Tag::query()->withMeta('info_prodotto:finalita', $value)->get();
155	
156	        if ($tags->isEmpty()) {
157	            throw new InvalidArgumentException("Nessun tag trovato per info_prodotto:finalita = \"{$value}\"");
158	        }
159	
160	        return $this->materials()->withAnyTags($tags);
161	    }
162	
163	    /**
164	     * Tessuti rivestibili (singolo colore).
165	     *
166	     * @return BelongsToMany<Fabric, $this>
167	     */
168	    public function fabrics(): BelongsToMany
169	    {
170	        return $this->belongsToMany(Fabric::class, 'fabric_product', 'product_id', 'fabric_id');
171	    }
172	
173	    /**
174	     * @return BelongsToMany<Environment, $this>
175	     */
176	    public function environments(): BelongsToMany
177	    {
178	        return $this->belongsToMany(Environment::class, 'environment_product', 'product_id', 'environment_id');
179	    }
180	}
