5	use Illuminate\Database\Migrations\Migration;
6	use Illuminate\Database\Schema\Blueprint;
7	use Illuminate\Support\Facades\Schema;
8	
9	return new class () extends Migration {
10	    public function up(): void
11	    {
12	        Schema::table('products', function (Blueprint $table) {
13	            // Composizione moduli/divani modulari via adjacency list: il "divano
14	            // modulare" è il padre (parent_id null), i moduli lo referenziano.
15	            $table->foreignId('parent_id')
16	                ->nullable()
17	                ->after('id')
18	                ->constrained('products')
19	                ->cascadeOnDelete();
20	
21	            // Specifica grezza del prodotto: codice/variante opaco + config sparsi
22	            // non promossi ad attributo tipizzato + backup della stringa originale.
23	            $table->string('specifica')->nullable()->after('slug');
24	        });
25	    }
26	
27	    public function down(): void
28	    {
29	        Schema::table('products', function (Blueprint $table) {
30	            $table->dropConstrainedForeignId('parent_id');
31	            $table->dropColumn('specifica');
32	        });
33	    }
34	};
