use App\Models\Category1;
use App\Models\User;
use Illuminate\Support\Facades\Auth;
use Spatie\Activitylog\Models\Activity;

$user = User::query()->first() ?? User::factory()->create();
Auth::login($user);
echo "auth id: ".Auth::id()."\n";

$c = Category1::create(['name' => ['it' => 'Verifica Log '.now()->timestamp], 'slug' => 'verifica-log-'.now()->timestamp]);
echo "created id: {$c->id}, updated_by: ".var_export($c->updated_by, true)."\n";

